import React, { useState } from "react";
import {
    Modal,
    ModalContent,
    ModalHeader,
    ModalBody,
    ModalFooter,
    Button,
} from "@heroui/react";
import { Select, SelectItem } from "@nextui-org/react";
import { useNavigate } from "react-router-dom";

export const ModalNavigate = ({ isOpen, onClose, title, list, schedule }) => {
    const navigate = useNavigate();
    const [value, setValue] = useState("");

    const handleSelection = (selected) => {
      setValue(selected);
    };

    const onAction = () => {
        navigate(`/schedule/${schedule}/${encodeURIComponent(list[value.currentKey].label)}`);
    }

    return (
        <Modal isOpen={isOpen} onOpenChange={onClose}>
            <ModalContent>
                <>
                    <ModalHeader className="flex flex-col gap-1">{title}</ModalHeader>
                    <ModalBody>
                            <Select
                                className="max-w-xs"
                                items={list}
                                label="Écrit ou fait défiler"
                                placeholder="Search a value"
                                variant="bordered"
                                onSelectionChange={handleSelection}
                            >
                                {(item) => <SelectItem key={item.key}>{item.label}</SelectItem>}
                            </Select>
                    </ModalBody>
                    <ModalFooter>
                        <Button color="danger" variant="light" onPress={onClose}>
                            Close
                        </Button>
                        <Button color="primary" onPress={onAction} isDisabled={value ? false: true}>
                            Go to Schedule
                        </Button>
                    </ModalFooter>
                </>
            </ModalContent>
        </Modal>
    );
};