import React, { useState, useEffect } from 'react';
import { Col, Container, Row, Table } from 'reactstrap';
import { Helmet } from 'react-helmet';
import Separator from '../components/separator';

const Inventory = ({ summaryJson, category }) => {
  const [items, setItems] = useState([]);

  useEffect(() => {
    if (summaryJson && summaryJson.fileMap) {
      const mappedItems = Object.keys(summaryJson.fileMap).map((fileName) => {
        const item = summaryJson.fileMap[fileName];

        const stock = 10;
        const total = stock * (item.pack || 0);

        return {
          ...item,
          category:category,
          stock,
          total,
        };
      });
      setItems(mappedItems);
    }
  }, [summaryJson]);

  return (
    <Container style={{ paddingTop: '20px' }}>
      <Table>
        <thead>
          <tr>
            <th>Category</th>
            <th>Name</th>
            <th>Number per Pack</th>
            <th>Total</th>
          </tr>
        </thead>
        <tbody>
          {items.map((item) => (
            <tr key={item.name}>
              <td>{item.category}</td>
              <td>{item.name}</td>
              <td>{item.pack}</td>
              <td>{item.total}</td>
            </tr>
          ))}
        </tbody>
      </Table>
    </Container>
  );
};

export default () => {

  return (
    <>
      <Helmet>
        <title>CISTEM - Inventory</title>
      </Helmet>

      <Row>
      <Col>
      <Separator title={'Inventory State'} />
      <Inventory summaryJson={require(`../assets/beer/summary.json`)} category="Bières" />
      </Col>
      <Col>
      <Separator title={'Logs'} />
      <Inventory summaryJson={require(`../assets/beer/summary.json`)} category="Bières" />
      </Col>
      </Row>
    </>
  );
};
